package org.traccar.tollpricing;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.locationtech.jts.geom.Coordinate;
import org.locationtech.jts.geom.LineSegment;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A distance-zoned facility as a line of interchanges with corridor km, generated by
 * {@code scripts/toll_research/build_407_corridor.py}. Turns an entry and an exit position into
 * a direction and km per rate zone.
 *
 * <p>Entry and exit are snapped outward to interchanges (decision 23 / gap 7): detection marks a
 * traversal up to one lookup late at entry and early at exit, while the operator bills the
 * interchange pair. Increasing km is eastbound.
 */
@JsonIgnoreProperties(ignoreUnknown = true)
public final class ZonedCorridor {

    public static final String EASTBOUND = "eastbound";
    public static final String WESTBOUND = "westbound";

    /** A point further than this from the corridor line is not on this facility. */
    static final double MAX_OFFSET_M = 2000;

    /**
     * A detected edge can project slightly past its interchange's centre (a toll-tagged ramp, a
     * merge after the bridge), so snapping tolerates this much before choosing the next interchange
     * out. Kept below half the tightest spacing (exits 65/66, 0.7 km) so it cannot jump a whole
     * interchange there. Recorded in every trip's inputs; tune it against a real statement.
     */
    public static final double SNAP_TOLERANCE_KM = 0.3;

    private static final double EARTH_RADIUS_M = 6371008.8;

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static final class Interchange {
        @JsonProperty("exit")
        private String exit;
        @JsonProperty("name")
        private String name;
        @JsonProperty("km")
        private double km;
        @JsonProperty("lat")
        private double lat;
        @JsonProperty("lon")
        private double lon;

        public String getExit() {
            return exit;
        }

        public String getName() {
            return name;
        }

        public double getKm() {
            return km;
        }
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static final class Zone {
        @JsonProperty("zone_code")
        private String zoneCode;
        @JsonProperty("from_km")
        private double fromKm;
        @JsonProperty("to_km")
        private double toKm;
    }

    /** Where a position lies along the corridor. */
    public record Projection(double km, double offsetMeters) {
    }

    /** An entry/exit pair after snapping. {@code beyondEnd} means the trip ran past the corridor's end. */
    public record SnappedTrip(String direction, Interchange entry, Interchange exit,
                              Map<String, Double> zoneKm, boolean beyondEnd) {
    }

    @JsonProperty("facility")
    private String facility;
    @JsonProperty("osm_base")
    private String osmBase;
    @JsonProperty("west_terminus_km")
    private double westTerminusKm;
    @JsonProperty("interchanges")
    private List<Interchange> interchanges;
    @JsonProperty("zones")
    private List<Zone> zones;

    public static ZonedCorridor load(InputStream in) throws IOException {
        ZonedCorridor corridor = new ObjectMapper().readValue(in, ZonedCorridor.class);
        if (corridor.interchanges == null || corridor.interchanges.size() < 2 || corridor.zones == null) {
            throw new IOException("corridor needs at least two interchanges and a zone table");
        }
        for (int i = 1; i < corridor.interchanges.size(); i++) {
            if (corridor.interchanges.get(i).km <= corridor.interchanges.get(i - 1).km) {
                throw new IOException("interchange km not increasing at exit " + corridor.interchanges.get(i).exit);
            }
        }
        return corridor;
    }

    public static ZonedCorridor loadResource(String name) throws IOException {
        try (InputStream in = ZonedCorridor.class.getResourceAsStream("/toll-pricing/corridors/" + name)) {
            if (in == null) {
                throw new IOException("corridor not on classpath: " + name);
            }
            return load(in);
        }
    }

    /** Local equirectangular metres around a reference latitude; ample over a 2 km offset test. */
    private static Coordinate toMeters(double lat, double lon, double refLat) {
        double x = Math.toRadians(lon) * Math.cos(Math.toRadians(refLat)) * EARTH_RADIUS_M;
        double y = Math.toRadians(lat) * EARTH_RADIUS_M;
        return new Coordinate(x, y);
    }

    /** Projects a position onto the interchange line, or {@code null} when it is off the corridor. */
    public Projection project(double lat, double lon) {
        Coordinate p = toMeters(lat, lon, lat);
        Projection best = null;
        int last = interchanges.size() - 1;
        for (int i = 0; i < last; i++) {
            Interchange a = interchanges.get(i);
            Interchange b = interchanges.get(i + 1);
            LineSegment segment = new LineSegment(toMeters(a.lat, a.lon, lat), toMeters(b.lat, b.lon, lat));
            double factor = segment.projectionFactor(p);
            // Interior segments clamp; the two end segments extrapolate, so the stretch west of
            // the first interchange (km 0 to QEW) and the corridor's far end still project.
            double f = Math.min(Math.max(factor, i == 0 ? Double.NEGATIVE_INFINITY : 0),
                    i == last - 1 ? Double.POSITIVE_INFINITY : 1);
            Coordinate onLine = segment.pointAlong(f);
            double offset = onLine.distance(p);
            if (best == null || offset < best.offsetMeters()) {
                best = new Projection(a.km + f * (b.km - a.km), offset);
            }
        }
        if (best == null || best.offsetMeters() > MAX_OFFSET_M) {
            return null;
        }
        return best;
    }

    /** Snaps outward to interchanges and splits the snapped span into km per zone, in travel order. */
    public SnappedTrip snap(double entryKm, double exitKm) {
        boolean east = exitKm >= entryKm;
        Interchange entry = east ? atOrBefore(entryKm + SNAP_TOLERANCE_KM) : atOrAfter(entryKm - SNAP_TOLERANCE_KM);
        Interchange exit = east ? atOrAfter(exitKm - SNAP_TOLERANCE_KM) : atOrBefore(exitKm + SNAP_TOLERANCE_KM);
        double maxKm = interchanges.get(interchanges.size() - 1).km;
        boolean beyondEnd = Math.max(entryKm, exitKm) > maxKm + SNAP_TOLERANCE_KM;

        double lo = Math.min(entry != null ? entry.km : westTerminusKm, exit != null ? exit.km : westTerminusKm);
        double hi = Math.max(entry != null ? entry.km : westTerminusKm, exit != null ? exit.km : westTerminusKm);

        Map<String, Double> zoneKm = new LinkedHashMap<>();
        List<Zone> ordered = new ArrayList<>(zones);
        if (!east) {
            Collections.reverse(ordered);
        }
        for (Zone z : ordered) {
            double from = z == zones.get(0) ? Math.min(z.fromKm, westTerminusKm) : z.fromKm;
            double overlap = Math.min(hi, z.toKm) - Math.max(lo, from);
            if (overlap > 1e-9) {
                zoneKm.put(z.zoneCode, Math.round(overlap * 1000) / 1000.0);
            }
        }
        return new SnappedTrip(east ? EASTBOUND : WESTBOUND, entry, exit, zoneKm, beyondEnd);
    }

    /** Last interchange at or before {@code km}; null means west of the first one (terminus). */
    private Interchange atOrBefore(double km) {
        Interchange found = null;
        for (Interchange ic : interchanges) {
            if (ic.km <= km) {
                found = ic;
            }
        }
        return found;
    }

    /** First interchange at or after {@code km}; the last one when past the end. */
    private Interchange atOrAfter(double km) {
        for (Interchange ic : interchanges) {
            if (ic.km >= km) {
                return ic;
            }
        }
        return interchanges.get(interchanges.size() - 1);
    }

    public String getFacility() {
        return facility;
    }

    /** Km of the last interchange: the corridor's far (east) end. */
    public double getEndKm() {
        return interchanges.get(interchanges.size() - 1).km;
    }

    public String getOsmBase() {
        return osmBase;
    }
}
